odal\\n- Preserve non-Error throws in extractErrorMessage fallback\\n- Let InvoiceTable accept discount data as optional props to dedupe fetch with Invoice\\n- Share line item total calculation between modal payload and table row\\n\\n---------\\n\\nCo-authored-by: Claude Opus 4.7 (1M context) <noreply@anthropic.com>\",\"authorName\":\"Nethmi Rodrigo\",\"authorEmail\":\"nethmi@openmrs.org\"},{\"hash\":\"276998ab31efde52652f58a4a22e099970ca615f\",\"date\":\"2026-05-06T03:05:16+05:30\",\"message\":\"(feat) Default bills table filter to \\\"Pending confirmation\\\" (#727)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"Nethmi Rodrigo\",\"authorEmail\":\"nethmi@openmrs.org\"},{\"hash\":\"db22701b986ae73bc876df2327fa0f82a7fd3ed5\",\"date\":\"2026-04-22T02:08:55+05:30\",\"message\":\"(feat) Add delete action for pending bills (#717)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"Nethmi Rodrigo\",\"authorEmail\":\"nethmi@openmrs.org\"},{\"hash\":\"311ffcf85b26822b024c384901d45667e680313e\",\"date\":\"2026-04-17T12:46:29-04:00\",\"message\":\"(feat) Migrate to RSpack and Vitest (#714)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"Ian\",\"authorEmail\":\"52504170+ibacher@users.noreply.github.com\"}],\"totalCount\":28}"}],"tool_result_meta":[{"id":"toolu_01E5XAkEv6tYEevVhLZZteeE","permission_decision":{"decision":"accept","source":"config","reason_type":"rule"}}]}
